#!/usr/bin/env node
/**
 * Generate the host app's route files from the pages each SIET part owns.
 *
 *   node scripts/frontend-routes.mjs           # write / update / delete the generated files
 *   node scripts/frontend-routes.mjs --check   # change nothing; exit 1 and list what would change
 *   make frontend-routes                       # same as the first line
 *
 * Next.js only serves routes it finds under its own app directory, but a part's
 * pages live in `<part>/frontend/src/app/`. For every file there named
 * page, layout, route, loading, error or not-found (.ts or .tsx) this script writes
 * the same relative path under `platform/frontend/src/app/`:
 *
 *     // generated by scripts/frontend-routes.mjs - edit the page in its part
 *     export { default } from '@siet/community/app/(dashboard)/community/page'
 *
 * so a part owner adds a page in their own part and never edits `platform/`.
 *
 *   part dir        alias (tsconfig paths and vitest)
 *   kmitl-rag       @siet/kmitl-rag
 *   community       @siet/community
 *   my-ai-quiz      @siet/quiz
 *   ai-roadmap      @siet/roadmap
 *
 * The stub differs from that shape in three cases:
 *   - route.ts(x): `export * from '...'` (a route module has named GET/POST/... and no default).
 *   - error.ts(x): the stub carries its own 'use client' line, because Next requires an
 *     error boundary file to be a client component.
 *   - the part file exports route segment config or metadata. Which way depends on the name,
 *     because Turbopack (the default for `next dev` and `next build`) fails the build on
 *     `export { dynamic } from '...'` with "can't recognize the exported `dynamic` field in
 *     route. It mustn't be reexported":
 *       copied as a literal, `export const dynamic = 'force-dynamic'` after the export line:
 *         dynamic, dynamicParams, revalidate, fetchCache, runtime, preferredRegion, maxDuration
 *       (maxDuration compiles when re-exported, but only the literal is known to be read);
 *       re-exported by name, `export { default, generateMetadata } from '...'`:
 *         metadata, generateMetadata, generateStaticParams, viewport, generateViewport.
 *     A copied name must be declared in the part file as `export const NAME = <literal>` where
 *     the literal is a string without escapes or `${}`, a number or a boolean (a `: Type`
 *     annotation, a trailing `;` or `// comment` are fine). Anything else (a ternary, an
 *     imported value, `const x = ...; export { x }`) makes the script refuse with exit 2 and
 *     "<file>: <NAME> must be a literal so the route stub can copy it". The stub is derived
 *     from the part file, so `--check` notices when the two drift apart.
 *
 * Exports are found with a regex over the source, not a parser. It sees
 * `export const|let|var|function|async function|class NAME` (the first name of a
 * `const a = 1, b = 2` list only) and `export { a, b as c }` lists (`export type` and
 * `type X` entries are skipped); it does not follow `export * from`, and `/* ... *\/`
 * inside a string literal can hide an export from it. If a part file hides one, declare
 * it in the plain form above.
 *
 * Ownership, so nothing hand-written is lost:
 *   - A file whose first line is the marker is generated: it is rewritten when the part
 *     file changes and deleted (with its directory, if that is left empty) when the part
 *     file is gone.
 *   - A host file without the marker is never overwritten. The one exception is the
 *     old hand-written stub, exactly `export { default } from '<the specifier this
 *     script would write>'`, which is converted to the generated form.
 *   - Anything else at a path a part also defines (real host code, a page defined by two
 *     parts, page.ts next to page.tsx) is refused: the script prints every such path to
 *     stderr, writes nothing, and exits 2.
 *
 * Exit codes: 0 up to date (or written), 1 --check found changes, 2 refused / bad usage.
 *
 * Paths are resolved from this file's location, not from the working directory, so
 * the script runs from anywhere (and in a temp copy of the layout, as the tests do).
 * ESM, no dependencies.
 */
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const HOST_APP = path.join(ROOT, 'platform', 'frontend', 'src', 'app')

const MARKER = '// generated by scripts/frontend-routes.mjs - edit the page in its part'

const PARTS = [
  { dir: 'kmitl-rag', alias: 'kmitl-rag' },
  { dir: 'community', alias: 'community' },
  { dir: 'my-ai-quiz', alias: 'quiz' },
  { dir: 'ai-roadmap', alias: 'roadmap' },
]

const ROUTE_FILES = new Set(['page', 'layout', 'route', 'loading', 'error', 'not-found'])
const EXTENSIONS = ['.ts', '.tsx']

// The part file's exports of these names reach the host stub. Order is the order they are written in.
const SEGMENT_CONFIG = [
  'dynamic',
  'dynamicParams',
  'runtime',
  'revalidate',
  'fetchCache',
  'preferredRegion',
  'maxDuration',
  'metadata',
  'generateMetadata',
  'generateStaticParams',
  'viewport',
  'generateViewport',
]
// Turbopack rejects these in `export { X } from '...'`, so the stub declares them as literals.
const COPIED_AS_LITERAL = new Set(['dynamic', 'dynamicParams', 'runtime', 'revalidate', 'fetchCache', 'preferredRegion', 'maxDuration'])

const toPosix = (p) => p.split(path.sep).join('/')
const fromRoot = (p) => toPosix(path.relative(ROOT, p))

function walk(dir) {
  if (!fs.existsSync(dir)) return []
  const found = []
  for (const entry of fs.readdirSync(dir, { withFileTypes: true }).sort((a, b) => (a.name < b.name ? -1 : 1))) {
    if (entry.name === 'node_modules' || entry.name.startsWith('.')) continue
    const full = path.join(dir, entry.name)
    if (entry.isDirectory()) found.push(...walk(full))
    else if (entry.isFile()) found.push(full)
  }
  return found
}

/** `{ base, ext }` when the file is a route file (page.tsx, route.ts, ...), else null. */
function routeFile(file) {
  const ext = path.extname(file)
  const base = path.basename(file, ext)
  return EXTENSIONS.includes(ext) && ROUTE_FILES.has(base) ? { base, ext } : null
}

const stripComments = (source) => source.replace(/\/\*[\s\S]*?\*\//g, '').replace(/^\s*\/\/.*$/gm, '')

/** Names from SEGMENT_CONFIG that the source exports, found with a regex (see the header). */
function segmentConfigExports(code) {
  const exported = new Set()
  const declaration = /^\s*export\s+(?:declare\s+)?(?:async\s+)?(?:const|let|var|function\s*\*?|class|enum)\s+([A-Za-z_$][\w$]*)/gm
  for (const match of code.matchAll(declaration)) exported.add(match[1])
  const list = /^\s*export\s*(type\s*)?\{([^}]*)\}/gm
  for (const match of code.matchAll(list)) {
    if (match[1]) continue
    for (const raw of match[2].split(',')) {
      const entry = raw.trim()
      if (!entry || /^type\s/.test(entry)) continue
      const alias = entry.split(/\s+as\s+/)
      exported.add(alias[alias.length - 1].trim())
    }
  }
  return SEGMENT_CONFIG.filter((name) => exported.has(name))
}

// A string without escapes or ${}, a number, or a boolean.
const LITERAL = String.raw`'[^'\\\n]*'|"[^"\\\n]*"|` + '`[^`$\\\\]*`' + String.raw`|-?\d[\d_]*(?:\.\d+)?(?:[eE][+-]?\d+)?|true|false`

/** The literal text of `export const NAME = <literal>`, or null when it is declared any other way. */
function literalDeclaration(code, name) {
  const declaration = new RegExp(
    String.raw`^[ \t]*export\s+const\s+${name}\s*(?::[^=\n]+)?=\s*(${LITERAL})[ \t]*;?[ \t]*(?:\/\/.*)?$`,
    'm'
  )
  const match = declaration.exec(code)
  return match ? match[1] : null
}

function stubFor(base, specifier, reexported, copied) {
  const lines = [MARKER]
  if (base === 'error') lines.push("'use client'")
  if (base === 'route') lines.push(`export * from '${specifier}'`)
  else lines.push(`export { ${['default', ...reexported].join(', ')} } from '${specifier}'`)
  for (const [name, literal] of copied) lines.push(`export const ${name} = ${literal}`)
  return lines.join('\n') + '\n'
}

const escapeRegExp = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')

/** The old hand-written stub for exactly this specifier. */
function isOneLineStub(content, specifier) {
  const old = new RegExp(`^export\\s*\\{\\s*default\\s*\\}\\s*from\\s*(['"])${escapeRegExp(specifier)}\\1;?$`)
  return old.test(content.trim())
}

const isGenerated = (content) => content.split('\n', 1)[0].trim() === MARKER

/** What the host app should contain: Map(host file -> { content, part file, specifier }). */
function collectDesired(problems) {
  const desired = new Map()
  const byRoute = new Map() // host path without extension -> part file that claimed it
  for (const part of PARTS) {
    const appDir = path.join(ROOT, part.dir, 'frontend', 'src', 'app')
    for (const file of walk(appDir)) {
      const kind = routeFile(file)
      if (!kind) continue
      const rel = toPosix(path.relative(appDir, file))
      const relNoExt = rel.slice(0, -kind.ext.length)
      const specifier = `@siet/${part.alias}/app/${relNoExt}`
      const hostFile = path.join(HOST_APP, ...rel.split('/'))
      const routeKey = hostFile.slice(0, -kind.ext.length)
      if (byRoute.has(routeKey)) {
        problems.push(`${fromRoot(hostFile)}: defined twice, by ${fromRoot(byRoute.get(routeKey))} and ${fromRoot(file)}`)
        continue
      }
      byRoute.set(routeKey, file)
      const code = stripComments(fs.readFileSync(file, 'utf8'))
      const reexported = []
      const copied = []
      let refused = false
      for (const name of segmentConfigExports(code)) {
        if (!COPIED_AS_LITERAL.has(name)) {
          reexported.push(name)
          continue
        }
        const literal = literalDeclaration(code, name)
        if (literal === null) {
          problems.push(`${fromRoot(file)}: ${name} must be a literal so the route stub can copy it`)
          refused = true
        } else copied.push([name, literal])
      }
      if (refused) continue
      desired.set(hostFile, { content: stubFor(kind.base, specifier, reexported, copied), source: file, specifier })
    }
  }
  return desired
}

function plan() {
  const problems = []
  const desired = collectDesired(problems)
  const writes = []
  const removals = []

  for (const [hostFile, { content, source, specifier }] of desired) {
    const ext = path.extname(hostFile)
    for (const other of EXTENSIONS.filter((e) => e !== ext)) {
      const sibling = hostFile.slice(0, -ext.length) + other
      if (fs.existsSync(sibling) && !isGenerated(fs.readFileSync(sibling, 'utf8'))) {
        problems.push(`${fromRoot(sibling)}: hand-written, next to ${fromRoot(hostFile)} generated from ${fromRoot(source)}`)
      }
    }
    if (!fs.existsSync(hostFile)) {
      writes.push({ hostFile, content })
      continue
    }
    const current = fs.readFileSync(hostFile, 'utf8')
    if (current === content) continue
    if (isGenerated(current) || isOneLineStub(current, specifier)) writes.push({ hostFile, content })
    else problems.push(`${fromRoot(hostFile)}: hand-written; the part defines the same page in ${fromRoot(source)}`)
  }

  for (const file of walk(HOST_APP)) {
    if (!routeFile(file) || desired.has(file)) continue
    if (isGenerated(fs.readFileSync(file, 'utf8'))) removals.push(file)
  }
  return { problems, writes, removals }
}

function pruneEmptyDirs(file) {
  for (let dir = path.dirname(file); dir !== HOST_APP && dir.startsWith(HOST_APP); dir = path.dirname(dir)) {
    if (fs.readdirSync(dir).length) return
    fs.rmdirSync(dir)
  }
}

function main(argv) {
  const check = argv.includes('--check')
  const unknown = argv.filter((arg) => arg !== '--check')
  if (unknown.length) {
    process.stderr.write(`usage: node scripts/frontend-routes.mjs [--check]\nunknown argument: ${unknown.join(' ')}\n`)
    return 2
  }

  const { problems, writes, removals } = plan()
  if (problems.length) {
    process.stderr.write('frontend-routes: refusing to touch these host files, nothing was written:\n')
    for (const problem of problems) process.stderr.write(`  ${problem}\n`)
    process.stderr.write('Move the page into its part (delete the host file) or remove the part file.\n')
    return 2
  }

  if (check) {
    for (const { hostFile } of writes) process.stdout.write(`would write  ${fromRoot(hostFile)}\n`)
    for (const file of removals) process.stdout.write(`would remove ${fromRoot(file)}\n`)
    if (writes.length || removals.length) {
      process.stderr.write('frontend-routes: out of date, run `make frontend-routes`\n')
      return 1
    }
    process.stdout.write('frontend-routes: up to date\n')
    return 0
  }

  for (const { hostFile, content } of writes) {
    fs.mkdirSync(path.dirname(hostFile), { recursive: true })
    fs.writeFileSync(hostFile, content)
    process.stdout.write(`wrote  ${fromRoot(hostFile)}\n`)
  }
  for (const file of removals) {
    fs.rmSync(file)
    pruneEmptyDirs(file)
    process.stdout.write(`removed ${fromRoot(file)}\n`)
  }
  if (!writes.length && !removals.length) process.stdout.write('frontend-routes: up to date\n')
  return 0
}

process.exitCode = main(process.argv.slice(2))
